CREATE TABLE IF NOT EXISTS doctor_availability (availability_id SERIAL PRIMARY KEY, doctor_id INTEGER NOT NULL REFERENCES doctors(doctor_id) ON DELETE CASCADE, day_of_week INTEGER NOT NULL CHECK (day_of_week BETWEEN 0 AND 6), start_time TIME NOT NULL, end_time TIME NOT NULL, slot_minutes INTEGER NOT NULL DEFAULT 60 CHECK (slot_minutes BETWEEN 15 AND 240), is_active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE (doctor_id, day_of_week, start_time, end_time));
CREATE TABLE IF NOT EXISTS doctor_reviews (review_id SERIAL PRIMARY KEY, doctor_id INTEGER NOT NULL REFERENCES doctors(doctor_id) ON DELETE CASCADE, patient_id INTEGER NOT NULL REFERENCES users(user_id) ON DELETE CASCADE, appointment_id INTEGER UNIQUE REFERENCES appointments(appointment_id) ON DELETE SET NULL, rating INTEGER NOT NULL CHECK (rating BETWEEN 1 AND 5), review_text TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE (doctor_id, patient_id, appointment_id));
CREATE TABLE IF NOT EXISTS prescriptions (prescription_id SERIAL PRIMARY KEY, appointment_id INTEGER UNIQUE REFERENCES appointments(appointment_id) ON DELETE CASCADE, doctor_id INTEGER NOT NULL REFERENCES doctors(doctor_id) ON DELETE CASCADE, patient_id INTEGER NOT NULL REFERENCES users(user_id) ON DELETE CASCADE, diagnosis TEXT, instructions TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS prescription_items (item_id SERIAL PRIMARY KEY, prescription_id INTEGER NOT NULL REFERENCES prescriptions(prescription_id) ON DELETE CASCADE, medicine_name VARCHAR(150) NOT NULL, dosage VARCHAR(100), frequency VARCHAR(100), duration VARCHAR(100), instructions TEXT);
CREATE INDEX IF NOT EXISTS idx_doctor_availability_doctor_day ON doctor_availability(doctor_id, day_of_week, is_active);
CREATE INDEX IF NOT EXISTS idx_doctor_reviews_doctor ON doctor_reviews(doctor_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_prescriptions_patient ON prescriptions(patient_id, created_at DESC);
